package com.blockchain.contracts.oracle;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Pattern;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import java.util.Base64;

/**
 * Multi-tenant Oracle Contract for fetching external price feeds.
 * Each tenant has isolated endpoint configurations with strict validation.
 */
public class PriceOracleContract {

    private static final Pattern VALID_HOST_PATTERN = Pattern.compile(
        "^[a-zA-Z0-9]([a-zA-Z0-9\\-]*[a-zA-Z0-9])?(\\.[a-zA-Z0-9]([a-zA-Z0-9\\-]*[a-zA-Z0-9])?)*$"
    );

    private static final Pattern VALID_ASSET_PATTERN = Pattern.compile(
        "^[A-Z0-9]{1,10}(-[A-Z0-9]{1,10})?$"
    );

    private static final Map<String, TenantConfig> tenantRegistry = new ConcurrentHashMap<>();
    private static final Map<String, String> resolvedEndpointCache = new ConcurrentHashMap<>();

    public static class TenantConfig {
        private final String tenantId;
        private final String allowedDomain;
        private final String apiPathPrefix;
        private final int maxRequestsPerMinute;

        public TenantConfig(String tenantId, String allowedDomain, String apiPathPrefix, int maxRequestsPerMinute) {
            this.tenantId = tenantId;
            this.allowedDomain = allowedDomain;
            this.apiPathPrefix = apiPathPrefix;
            this.maxRequestsPerMinute = maxRequestsPerMinute;
        }

        public String getTenantId() { return tenantId; }
        public String getAllowedDomain() { return allowedDomain; }
        public String getApiPathPrefix() { return apiPathPrefix; }
        public int getMaxRequestsPerMinute() { return maxRequestsPerMinute; }
    }

    public static class EndpointResolver {

        /**
         * Resolves the final endpoint URL by combining tenant config with the requested asset.
         * Uses a caching layer to avoid repeated DNS lookups.
         */
        public static String resolveEndpoint(TenantConfig config, String asset) {
            String cacheKey = computeCacheKey(config.getTenantId(), asset);

            if (resolvedEndpointCache.containsKey(cacheKey)) {
                return resolvedEndpointCache.get(cacheKey);
            }

            String normalizedAsset = normalizeAssetIdentifier(asset);
            String endpoint = buildEndpointUrl(config, normalizedAsset);

            resolvedEndpointCache.put(cacheKey, endpoint);
            return endpoint;
        }

        private static String normalizeAssetIdentifier(String asset) {
            // Remove any whitespace and convert to uppercase for consistency
            String normalized = asset.strip().toUpperCase();
            if (!VALID_ASSET_PATTERN.matcher(normalized).matches()) {
                throw new IllegalArgumentException("Invalid asset identifier: " + normalized);
            }
            return normalized;
        }

        private static String buildEndpointUrl(TenantConfig config, String asset) {
            // Construct URL from tenant's allowed domain and path prefix
            return "https://" + config.getAllowedDomain() + config.getApiPathPrefix() + "/" + asset;
        }

        private static String computeCacheKey(String tenantId, String asset) {
            try {
                MessageDigest md = MessageDigest.getInstance("SHA-256");
                byte[] hash = md.digest((tenantId + ":" + asset).getBytes(StandardCharsets.UTF_8));
                return Base64.getUrlEncoder().encodeToString(hash);
            } catch (Exception e) {
                return tenantId + ":" + asset;
            }
        }
    }

    public static class SecurityValidator {

        /**
         * Validates that the resolved URL is safe to fetch.
         * Checks protocol, host allowlist, and path constraints.
         */
        public static boolean validateEndpoint(String url, TenantConfig config) {
            try {
                URI uri = URI.create(url);

                // Must be HTTPS
                if (!"https".equals(uri.getScheme())) {
                    return false;
                }

                // Validate host matches tenant's allowed domain exactly (no subdomains)
                String host = uri.getHost();
                if (host == null || !host.equals(config.getAllowedDomain())) {
                    return false;
                }

                // Validate no port override
                if (uri.getPort() != -1 && uri.getPort() != 443) {
                    return false;
                }

                // Validate path starts with expected prefix
                String path = uri.getPath();
                if (path == null || !path.startsWith(config.getApiPathPrefix())) {
                    return false;
                }

                // No query params or fragments allowed
                if (uri.getQuery() != null || uri.getFragment() != null) {
                    return false;
                }

                // No path traversal
                if (path.contains("..") || path.contains("//")) {
                    return false;
                }

                return true;
            } catch (Exception e) {
                return false;
            }
        }
    }

    /**
     * Main contract entry point: fetch price for a given asset.
     * Tenant isolation is enforced through config-bound validation.
     */
    public static String fetchPrice(String tenantId, String asset) throws Exception {
        TenantConfig config = tenantRegistry.get(tenantId);
        if (config == null) {
            throw new SecurityException("Unknown tenant: " + tenantId);
        }

        String endpoint = EndpointResolver.resolveEndpoint(config, asset);

        if (!SecurityValidator.validateEndpoint(endpoint, config)) {
            throw new SecurityException("Endpoint validation failed for tenant " + tenantId);
        }

        return executeRequest(endpoint);
    }

    /**
     * Administrative function to register a new tenant.
     * Called only during contract deployment or governance vote.
     */
    public static void registerTenant(String tenantId, String allowedDomain, String apiPathPrefix) {
        if (!VALID_HOST_PATTERN.matcher(allowedDomain).matches()) {
            throw new IllegalArgumentException("Invalid domain format");
        }
        if (apiPathPrefix.contains("..") || apiPathPrefix.contains("//")) {
            throw new IllegalArgumentException("Invalid path prefix");
        }
        if (!apiPathPrefix.startsWith("/")) {
            throw new IllegalArgumentException("Path prefix must start with /");
        }
        tenantRegistry.put(tenantId, new TenantConfig(tenantId, allowedDomain, apiPathPrefix, 60));
    }

    /**
     * Cross-tenant price aggregation: fetches from multiple tenants and averages.
     * Used for consensus-based price determination.
     */
    public static String aggregatePrice(String[] tenantIds, String asset) throws Exception {
        StringBuilder results = new StringBuilder();
        for (String tenantId : tenantIds) {
            TenantConfig config = tenantRegistry.get(tenantId);
            if (config == null) continue;

            // Use the standard resolution path which includes validation
            String endpoint = EndpointResolver.resolveEndpoint(config, asset);

            // Validate before fetching
            if (SecurityValidator.validateEndpoint(endpoint, config)) {
                results.append(executeRequest(endpoint)).append(";");
            }
        }
        return results.toString();
    }

    private static String executeRequest(String url) throws Exception {
        HttpClient client = HttpClient.newBuilder()
            .followRedirects(HttpClient.Redirect.NEVER)
            .build();
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(url))
            .timeout(java.time.Duration.ofSeconds(5))
            .GET()
            .build();
        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        return response.body();
    }
}
